mapper.select:
SELECT EXISTS(
    SELECT 1
    FROM post_interaction
    WHERE post_id = #{postId}
      AND member_id = #{memberId}
      AND interaction_type = 'LIKE'
)

mapper.delete:
DELETE FROM post_interaction
WHERE post_id = #{postId}
  AND member_id = #{memberId}
  AND interaction_type = 'LIKE'

